import { tags } from "typia";

/**
 * Daily aggregated payment metrics for trend visualization in dashboards.
 *
 * Each instance represents a single calendar day within the analysis window and
 * aggregates payment and refund metrics for that day. Intended for use in
 * `IShoppingMallPaymentsOverview.byDay` to draw time-series charts and to
 * support drill-down into per-day payment performance.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallPaymentsOverviewByDay = {
  /**
   * Calendar date in ISO 8601 `YYYY-MM-DD` format representing the day for
   * which the aggregated metrics are calculated.
   *
   * The date is always expressed in the platform's configured reporting
   * timezone so that daily buckets align with business reporting expectations
   * rather than raw UTC boundaries.
   */
  date: string & tags.Format<"date">;

  /**
   * Total processed payment volume for this date, based on successful
   * transactions captured on that day.
   *
   * The value is expressed in the platform's base currency (for example, KRW
   * or another configured settlement currency) and is aggregated from
   * captured payment transaction records that match the analytics filters and
   * fall on the given calendar date.
   */
  totalProcessedAmount: number;

  /**
   * Number of successful payment transactions on this date.
   *
   * This count generally includes all transactions that reached a terminal
   * success state (such as `SUCCEEDED` or equivalent) according to the
   * business rules in the payments subsystem.
   */
  successfulTransactionCount: number & tags.Type<"int32">;

  /**
   * Number of failed payment transactions on this date.
   *
   * This metric captures transactions that reached a terminal failed state
   * (for example, authorization failure, capture failure, or gateway error)
   * and is useful for identifying reliability issues or incident windows in
   * the payment infrastructure.
   */
  failedTransactionCount: number & tags.Type<"int32">;

  /**
   * Total amount refunded on this date as recorded in
   * `shopping_mall_refund_transactions` and related tables.
   *
   * The value is expressed in the same platform base currency as
   * `totalProcessedAmount` and aggregates refund transactions whose effective
   * refund date falls on this calendar day under the reporting timezone
   * configuration.
   */
  refundAmount?: number | undefined;
};
